public final class ContextDependentCandidateModelRunner {
    private static int checks;
    private interface Attempt{void run()throws Exception;}
    private static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
    private static void reject(Attempt a,String why)throws Exception{boolean no=false;try{a.run();}catch(Exception expected){no=true;}require(no,why);}
    private static Mind memory()throws Exception{User u=new User();Mind m=new Mind(u);u.setCurrentMind(m);return m;}
    private static Rule raw(Mind m,String text)throws Exception{return (Rule)m.compileLine(text,false,new LinkedList<ITerm>());}
    private static Policy policy(){return new Policy(2000000,1000,1000,64000000,200000);}
    private static Member member(Mind m,int id,boolean local)throws Exception{return new Member(m,ContextProductionInventory.inspect(m,new UUID(0,id),3,local,Collections.emptyList(),1000));}
    private static Source source(Member m,long rule){return new Source(m.inventory.context,m.inventory.revision,rule,m.inventory.localX,"inventory:"+m.inventory.fingerprint);}
    private static SemanticTermSnapshot value(String literal)throws Exception{Mind m=memory();Rule r=raw(m,"!value("+literal+");");return SemanticTermSnapshot.capture(r.getDomain().get(0).getValue(m));}
    private static Model model(List<SemanticTermSnapshot> points,SemanticTermSnapshot other,String[] names,int[] arities,boolean[] truth,Map<Function,Choice> functions){Map<Signature,Relation> rels=new LinkedHashMap<>();for(int i=0;i<names.length;i++)rels.put(new Signature(names[i],arities[i]),new Relation(truth[i],Collections.emptyMap()));return new Model(points,other,rels,functions);}
    private static ContextDependentCandidateInspection.Request append(int rounds,String... text){return new ContextDependentCandidateInspection.Request(new ContextDependentIterationInspection.Request(policy(),10000,rounds),Arrays.asList(text));}
    private static Request request(ContextDependentCandidateInspection.Request append,Map<String,Model> base,Map<String,Model> proposed,int bo,int bf,int po,int pf){return new Request(append,base,proposed,20,100000,bo,bf,po,pf);}
    private static Request request(ContextDependentCandidateInspection.Request append,Map<String,Model> base,Map<String,Model> proposed){return request(append,base,proposed,4000000,4000000,4000000,4000000);}
    private static Map<String,Model> local(Member base,Model model){return Collections.singletonMap(ContextDependentCutInspection.local(base.inventory.context),model);}
    private static void incomplete(Result r,String phase,String why){require(r.status==Status.INCOMPLETE&&r.phase.equals(phase),why+" actual="+r.status+"/"+r.phase+"/"+r.reason);require(r.candidate==null&&r.baseOriginalRows==0&&r.baseFinalObligations==0&&r.proposedOriginalRows==0&&r.proposedFinalObligations==0&&r.reboundFunctions.isEmpty(),"no append/base/model prefix survives incomplete composition");}
    private static void fourAudits()throws Exception{
        Mind parent=memory();raw(parent,"!seed(1);");raw(parent,"!@x seed(x)->p(x);");Member base=member(parent,1,true);Mind child=new Mind(parent);Rule h=raw(child,"!@x p(x)->q(x);");Member proposed=member(child,1,true);SemanticTermSnapshot one=value("1"),other=value("2");Model b=model(Collections.singletonList(one),other,new String[]{"seed","p"},new int[]{1,1},new boolean[]{true,true},Collections.emptyMap()),p=model(Collections.singletonList(one),other,new String[]{"seed","p","q"},new int[]{1,1,1},new boolean[]{true,true,true},Collections.emptyMap());ContextDependentCandidateInspection.Request append=append(10,h.getOrigin());Request request=request(append,local(base,b),local(base,p));int terms=child.getTerms().size();Result r=ContextDependentCandidateModelInspection.inspect(base,proposed,Collections.emptyList(),request);require(r.status==Status.MODELLED_PENDING&&r.baseOriginalRows==2&&r.baseFinalObligations==4&&r.proposedOriginalRows==3&&r.proposedFinalObligations==12,"one actual append passes all four complete independent model audits");require(r.candidate.verdict==ContextDependentCandidateInspection.Verdict.STABLE_PENDING&&r.candidate.originals.size()==3,"fresh exact append evidence retained only on combined success");require(r.reason.contains("admission unknown"),"modelled pending is not native write authority");require(child.getTerms().size()==terms&&proposed.inventory.fingerprint.equals(ContextProductionInventory.inspect(child,proposed.inventory.context,3,true,Collections.emptyList(),1000).fingerprint),"composition creates no actual product Terms/facts");reject(()->request.proposedOriginalModels.clear(),"request model namespace frozen");reject(()->r.reboundFunctions.clear(),"rebinding manifest immutable");
        incomplete(ContextDependentCandidateModelInspection.inspect(base,proposed,Collections.emptyList(),request(append,local(base,b),local(base,p),1,4000000,4000000,4000000)),"base-model-preflight","base original budget independent");incomplete(ContextDependentCandidateModelInspection.inspect(base,proposed,Collections.emptyList(),request(append,local(base,b),local(base,p),4000000,1,4000000,4000000)),"base-actual-final-audit","base actual-final budget cannot be skipped");incomplete(ContextDependentCandidateModelInspection.inspect(base,proposed,Collections.emptyList(),request(append,local(base,b),local(base,p),4000000,4000000,1,4000000)),"proposed-model-preflight","proposed original budget independent");incomplete(ContextDependentCandidateModelInspection.inspect(base,proposed,Collections.emptyList(),request(append,local(base,b),local(base,p),4000000,4000000,4000000,1)),"proposed-actual-final-audit","last failed audit drops all three earlier successful prefixes");
        Model falseBase=model(Collections.singletonList(one),other,new String[]{"seed","p"},new int[]{1,1},new boolean[]{false,true},Collections.emptyMap());incomplete(ContextDependentCandidateModelInspection.inspect(base,proposed,Collections.emptyList(),request(append,local(base,falseBase),local(base,p))),"base-original-audit","bad base interpretation is not a refutation");Model falseProposed=model(Collections.singletonList(one),other,new String[]{"seed","p","q"},new int[]{1,1,1},new boolean[]{true,true,false},Collections.emptyMap());incomplete(ContextDependentCandidateModelInspection.inspect(base,proposed,Collections.emptyList(),request(append,local(base,b),local(base,falseProposed))),"proposed-original-audit","base model success does not certify proposed state");incomplete(ContextDependentCandidateModelInspection.inspect(base,proposed,Collections.emptyList(),request(append,local(base,b),Collections.emptyMap())),"proposed-model-preflight","every proposed exact cut model required");parent.release(child);
    }
    private static void rebaseAndChoices()throws Exception{
        SemanticTermSnapshot one=value("1"),two=value("2"),other=value("3");Mind parent=memory();Rule seed=raw(parent,"!$u p(u);");Member base=member(parent,2,true);Mind child=new Mind(parent);Rule h=raw(child,"!~p(1);");Member proposed=member(child,2,true);Function original=new Function(source(base,seed.getId()),0),actual=new Function(source(proposed,seed.getId()),0);Map<Signature,Relation> bRel=Collections.singletonMap(new Signature("p",1),new Relation(false,Collections.singletonMap(Collections.singletonList(0),true))),pRel=Collections.singletonMap(new Signature("p",1),new Relation(false,Collections.singletonMap(Collections.singletonList(1),true)));Model before=new Model(Arrays.asList(one,two),other,bRel,Collections.singletonMap(original,new Choice(0,0,Collections.emptyMap()))),after=new Model(Arrays.asList(one,two),other,pRel,Collections.singletonMap(original,new Choice(0,1,Collections.emptyMap())));String key=ContextDependentCutInspection.local(base.inventory.context);Request req=request(append(5,h.getOrigin()),local(base,before),local(base,after));int terms=child.getTerms().size();Result r=ContextDependentCandidateModelInspection.inspect(base,proposed,Collections.emptyList(),req);require(r.status==Status.MODELLED_PENDING&&r.reboundFunctions.get(key).get(original).equals(actual),"preserved function explicitly rebound from parent to actual child namespace");require(!original.equals(actual),"whole-view Source change is real, not silently ignored");require(child.getTerms().size()==terms&&((Term)seed.getDomain().get(0).getValue(parent)).isCVariable()&&((Term)seed.getDomain().get(0).getValue(parent)).getParent(child)==null,"base/proposed model choices may differ without assigning actual Cvar values");reject(()->r.reboundFunctions.get(key).clear(),"per-cut function rebasing immutable");
        Model wrongSpace=new Model(after.points,after.otherRepresentative,after.relations,Collections.singletonMap(actual,new Choice(0,1,Collections.emptyMap())));incomplete(ContextDependentCandidateModelInspection.inspect(base,proposed,Collections.emptyList(),request(req.append,local(base,before),local(base,wrongSpace))),"proposed-model-rebase","actual-child preserved key is refused in explicitly parent-original input namespace");Source stale=new Source(original.source.context,4,original.source.rule,true,original.source.view);Model staleModel=new Model(after.points,after.otherRepresentative,after.relations,Collections.singletonMap(new Function(stale,0),new Choice(0,1,Collections.emptyMap())));incomplete(ContextDependentCandidateModelInspection.inspect(base,proposed,Collections.emptyList(),request(req.append,local(base,before),local(base,staleModel))),"proposed-model-rebase","stale physical Source cannot be repaired by text/native ID alone");Model badRank=new Model(after.points,after.otherRepresentative,after.relations,Collections.singletonMap(original,new Choice(1,1,Collections.emptyMap())));incomplete(ContextDependentCandidateModelInspection.inspect(base,proposed,Collections.emptyList(),request(req.append,local(base,before),local(base,badRank))),"proposed-model-preflight","rebasing does not relax exact dependency-rank validation");parent.release(child);
        Mind np=memory();raw(np,"!anchor(1);");Member nb=member(np,3,true);Mind nc=new Mind(np);Rule exists=raw(nc,"!$v q(v);");Member nn=member(nc,3,true);Function added=new Function(source(nn,exists.getId()),0);Model bm=model(Collections.singletonList(one),two,new String[]{"anchor"},new int[]{1},new boolean[]{true},Collections.emptyMap()),pm=model(Collections.singletonList(one),two,new String[]{"anchor","q"},new int[]{1,1},new boolean[]{true,true},Collections.singletonMap(added,new Choice(0,0,Collections.emptyMap())));Result addedResult=ContextDependentCandidateModelInspection.inspect(nb,nn,Collections.emptyList(),request(append(5,exists.getOrigin()),local(nb,bm),local(nb,pm)));require(addedResult.status==Status.MODELLED_PENDING&&addedResult.reboundFunctions.get(ContextDependentCutInspection.local(nb.inventory.context)).get(added).equals(added),"new incoming declaration stays exact actual-child Source");np.release(nc);
    }
    private static void ranksAndRefutations()throws Exception{
        SemanticTermSnapshot other=value("9");for(int width:new int[]{1,7,17,65}){Mind parent=memory();StringBuilder prefix=new StringBuilder(),args=new StringBuilder();for(int i=0;i<width;i++){prefix.append("@x").append(i).append(' ');if(i>0)args.append(',');args.append('x').append(i);}Rule seed=raw(parent,"!"+prefix+"$u rel("+args+",u);");Member base=member(parent,100+width,true);Mind child=new Mind(parent);Rule h=raw(child,"!"+prefix+"@u rel("+args+",u)->out("+args+",u);");Member proposed=member(child,100+width,true);Function f=new Function(source(base,seed.getId()),width);Map<Function,Choice> choices=Collections.singletonMap(f,new Choice(width,0,Collections.emptyMap()));Model b=model(Collections.emptyList(),other,new String[]{"rel"},new int[]{width+1},new boolean[]{true},choices),p=model(Collections.emptyList(),other,new String[]{"rel","out"},new int[]{width+1,width+1},new boolean[]{true,true},choices);Result r=ContextDependentCandidateModelInspection.inspect(base,proposed,Collections.emptyList(),request(append(5,h.getOrigin()),local(base,b),local(base,p)));require(r.status==Status.MODELLED_PENDING&&r.proposedFinalObligations>0,"all four audits preserve supported rank "+width);ContextDependentProductionInspection.TermView witness=r.candidate.proposed.frontier.common.get(0).arguments.get(width);require(r.reboundFunctions.get(ContextDependentCutInspection.local(base.inventory.context)).get(f).source.equals(witness.symbolSource),"rebound model declaration is exact actual carrier function");for(int i=0;i<width;i++)require(witness.arguments.get(i)==r.candidate.proposed.frontier.common.get(0).arguments.get(i),"rebasing preserves dependency coordinate "+i);parent.release(child);}
        Mind p=memory();raw(p,"!p(1);");Member b=member(p,201,true);Mind c=new Mind(p);Rule no=raw(c,"!~p(1);");Result conflict=ContextDependentCandidateModelInspection.inspect(b,member(c,201,true),Collections.emptyList(),request(append(5,no.getOrigin()),Collections.emptyMap(),Collections.emptyMap()));require(conflict.status==Status.CANDIDATE_REFUTED&&conflict.candidate.oppositions.stream().allMatch(o->!o.candidates.isEmpty()),"fresh sourced incoming refutation does not depend on supplied model success");require(conflict.baseOriginalRows==0&&conflict.proposedFinalObligations==0,"refutation result does not pretend models were audited");p.release(c);
        Mind broken=memory();raw(broken,"!p(1);");raw(broken,"!~p(1);");Member old=member(broken,202,true);Mind next=new Mind(broken);Rule q=raw(next,"!q(1);");Result existing=ContextDependentCandidateModelInspection.inspect(old,member(next,202,true),Collections.emptyList(),request(append(5,q.getOrigin()),Collections.emptyMap(),Collections.emptyMap()));require(existing.status==Status.BASE_REFUTED&&existing.candidate.oppositions.stream().allMatch(o->o.candidates.isEmpty()),"base refutation never blames proposed statement");broken.release(next);
    }
    private static final class Fixture implements AutoCloseable{
        final User user=new User();final DB db=new DB();final Mind root;
        Fixture(Path d,String name)throws Exception{user.setDatabaseDir(d+File.separator);user.setUserDir(Files.createDirectories(d.resolve("operator")).toString());db.init(user);Mind m=new Mind(user);user.setCurrentMind(m);root=(Mind)m.useStorage(name);user.setCurrentMind(root);}
        @Override public void close()throws Exception{if(user.getCurrentMind().isStorageUsed())user.setCurrentMind(user.getCurrentMind().closeStorage());}
    }
    private static void owning()throws Exception{
        Path dir=Files.createTempDirectory("candidate-model-db-");try(Fixture a=new Fixture(dir,"A")){require(a.root.compile("!p(1);",null,false),"A fixture");}try(Fixture b=new Fixture(dir,"B")){require(b.root.compile("!~p(1);",null,false),"B fixture");}
        SemanticTermSnapshot one=value("1"),other=value("2");for(boolean reverse:new boolean[]{false,true})try(Fixture f=new Fixture(dir,"X"+reverse)){require(f.root.compile("!seed(1);",null,false),"actual parent");f.db.connectContext(reverse?"B":"A");f.db.connectContext(reverse?"A":"B");long revision=f.db.getRevision();String parent=ContextProductionInventory.inspect(f.root,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint;Mind child=new Mind(f.root);Rule h=raw(child,"!@x seed(x)->out(x);");Map<String,Model> baseModels=new LinkedHashMap<>(),proposedModels=new LinkedHashMap<>();String local=ContextDependentCutInspection.local(f.db.getContextId());baseModels.put(local,model(Collections.singletonList(one),other,new String[]{"seed"},new int[]{1},new boolean[]{true},Collections.emptyMap()));proposedModels.put(local,model(Collections.singletonList(one),other,new String[]{"seed","out"},new int[]{1,1},new boolean[]{true,true},Collections.emptyMap()));for(ContextConnection connection:f.db.dmzTopology()){boolean positive=false;for(Object obj:connection.layer().getRules())positive|=((Rule)obj).getOrigin().equals("!p(1);");String cut=ContextDependentCutInspection.independent(connection.getTarget().getContextId());baseModels.put(cut,model(Collections.singletonList(one),other,new String[]{"seed","p"},new int[]{1,1},new boolean[]{true,positive},Collections.emptyMap()));proposedModels.put(cut,model(Collections.singletonList(one),other,new String[]{"seed","out","p"},new int[]{1,1,1},new boolean[]{true,true,positive},Collections.emptyMap()));}String before=ContextProductionInventory.inspect(child,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint;ContextDependentCandidateInspection.Request append=append(5,h.getOrigin());try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,1000)){Result r=lease.inspectDependentCandidateModels(request(append,baseModels,proposedModels));require(r.status==Status.MODELLED_PENDING&&r.baseOriginalRows==5&&r.proposedOriginalRows==8&&r.proposedFinalObligations>0,"actual owning append and all four whole-family models audited in either attachment order");require(f.db.getRevision()==revision&&before.equals(ContextProductionInventory.inspect(child,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint),"combined owning path writes no actual child/revision");incomplete(lease.inspectDependentCandidateModels(request(append,baseModels,proposedModels,4000000,4000000,4000000,1)),"proposed-actual-final-audit","late provider failure exposes no earlier accepted proof/model prefix");raw(child,"!changed(1);");reject(()->lease.inspectDependentCandidateModels(request(append,baseModels,proposedModels)),"whole child currentness remains mandatory after combined audit");}finally{f.root.release(child);}require(parent.equals(ContextProductionInventory.inspect(f.root,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint),"actual parent unchanged after release");}
    }
    public static void main(String[] args){try{System.setProperty("user.home",Files.createTempDirectory("candidate-model-").toString());fourAudits();rebaseAndChoices();ranksAndRefutations();owning();System.out.println("CONTEXT_DEPENDENT_CANDIDATE_MODEL_PASS checks="+checks);System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
